#!/bin/sh
# Interaction tests with REAL input events, generated by a virtual pointer
# and keyboard inside an isolated headless compositor, plus real clients
# (windows and a layer-shell panel) that report what they receive.
#
# Requires the test build:  zig build -Dtest-input -p zig-out/test-input
# Isolation: private XDG_RUNTIME_DIR, scrubbed environment (env -i); the
# driver connects only to the test compositor's socket. Nothing is sent to
# the running desktop session.
#   usage: [RENDERER=pixman|gles2] [KEEP=1] tests/input.sh [test-bin-dir]
set -eu
bin=$(cd "${1:-zig-out/test-input/bin}" && pwd)
root=$(cd "$(dirname "$0")/.." && pwd)
[ -x "$bin/raywm-test-input" ] || { echo "input: missing $bin/raywm-test-input (build with -Dtest-input)"; exit 2; }
. "$root/tests/support/harness.sh"

# ---- floating windows: free interactive move/resize -----------------------
s1() {
    name="floating: Super+drag, Super+resize, CSD move"
    start "$root/tests/input/floating.lua" 1
    dump                                                                      # 1
    expect 1 "view 2 540,285 200x150 focused=true"
    drive move 600 350 key super down down left move 700 450 up left key super up
    dump                                                                      # 2
    expect 2 "view 2 640,385 200x150 focused=true"
    drive move 800 500 key super down down right move 850 540 up right key super up sleep 300
    dump                                                                      # 3
    expect 3 "view 2 640,385 250x190 focused=true"
    drive move 700 450 down left sleep 200 move 760 470 up left sleep 100
    dump                                                                      # 4
    expect 4 "view 2 700,405 250x190 focused=true"
    grep -q "csd move requested" "$tmp/a.log" || fail "client did not request a move"
    stop

}

# ---- managed (dwindle-tiled) windows: no free move/resize -----------------
s2() {
    name="managed: drag/resize/CSD move refused, click focuses"
    start "$root/tests/input/managed.lua" 2
    dump                                                                      # 1
    expect 1 "view 2 8,8 628x704 focused=false"
    expect 1 "view 3 644,8 628x704 focused=true"
    drive move 300 300 key super down down left move 500 400 up left key super up
    dump                                                                      # 2
    expect 2 "view 2 8,8 628x704 focused=true"
    expect 2 "view 3 644,8 628x704 focused=false"
    drive move 600 600 key super down down right move 640 650 up right key super up sleep 300
    dump                                                                      # 3
    expect 3 "view 2 8,8 628x704 focused=true"
    drive move 900 300 down left sleep 200 move 1000 400 up left sleep 100
    dump                                                                      # 4
    expect 4 "view 3 644,8 628x704 focused=true"
    expect 4 "view 2 8,8 628x704 focused=false"
    grep -q "csd move requested" "$tmp/b.log" || fail "client B did not request a move"
    stop

}

# ---- a binding's key must not leak into the newly focused client ----------
s3() {
    name="binding key not reported as held after a focus change"
    start "$root/tests/navigation/tiled.lua" 2
    # One driver run, so the virtual keyboard (and the clients' wl_keyboard)
    # exists throughout: wait, dump 1, Super+H (focus.lua: left), dump 2.
    f12="key super down key f12 down key f12 up key super up sleep 150"
    drive sleep 400 $f12 key super down key h down key h up key super up sleep 150 $f12
    expect 1 "view 3 644,8 628x704 focused=true"
    expect 2 "view 2 8,8 628x704 focused=true"
    enter=$(grep "client: kbd enter" "$tmp/a.log" | tail -1)
    [ -n "$enter" ] || fail "A never got keyboard focus"
    case "$enter " in *" 35 "*) fail "H (35) reported as held in A's enter: $enter" ;; esac
    if grep -q "kbd key 35" "$tmp/a.log" "$tmp/b.log"; then fail "H events leaked to a client"; fi
    stop

}

# ---- view_place twice before the ack; out-of-range coordinates ------------
s4() {
    name="second place before ack wins; huge coordinates are clamped"
    start "$root/tests/input/placer.lua" 1
    drive sleep 400
    dump                                                                      # 1
    expect 1 "view 2 100,100 200x150 focused=true"
    stop

}

# ---- a window becomes managed in the middle of a drag ---------------------
s5() {
    name="managed mid-drag stops the drag"
    start "$root/tests/input/floating.lua" 1
    drive move 600 350 key super down down left move 650 400 key f11 down key f11 up move 750 500 up left key super up
    dump                                                                      # 1
    expect 1 "view 2 590,335 200x150 focused=true"
    stop

}

# ---- other buttons during a grab do not end or steal it -------------------
s6() {
    name="extra button during a grab"
    start "$root/tests/input/floating.lua" 1
    drive move 600 350 key super down down left move 650 400 down right up right move 700 450 up left key super up
    dump                                                                      # 1
    expect 1 "view 2 640,385 200x150 focused=true"
    stop

}

# ---- panel exclusive zone, panel crash, window crash ----------------------
s7() {
    name="panel removal and client crashes re-tile"
    start "$root/tests/input/managed.lua" 2 panel
    dump                                                                      # 1
    expect 1 "view 2 8,38 628x674 focused=false"
    expect 1 "view 3 644,38 628x674 focused=true"
    grep -q "client: layer configured 1280x30" "$tmp/panel.log" || fail "panel not configured to the output width"
    kill -9 "$(cat "$tmp/panel.pid")"; sleep 0.5
    dump                                                                      # 2
    expect 2 "view 2 8,8 628x704 focused=false"
    expect 2 "view 3 644,8 628x704 focused=true"
    kill -9 "$(cat "$tmp/b.pid")"; sleep 0.5
    dump                                                                      # 3
    expect 3 "view 2 8,8 1264x704 focused=true"
    stop

}

# ---- a launcher-like layer surface releases the keyboard ------------------
s8() {
    name="layer keyboard interactivity change"
    start "$root/tests/input/floating.lua" 1 panel-kbd
    # (pause first: clients request a wl_keyboard once the virtual one exists)
    drive sleep 300 key f11 down key f11 up sleep 300   # goes to the exclusive panel
    grep -q "client: kbd key 87 pressed" "$tmp/panel.log" || fail "exclusive panel did not get the key"
    grep -q "client: layer kbd none" "$tmp/panel.log" || fail "panel did not switch interactivity"
    grep -q "client: kbd leave" "$tmp/panel.log" || fail "panel kept the keyboard"
    grep -q "client: kbd enter" "$tmp/a.log" || fail "window did not get the keyboard back"
    # The press went to the panel. Depending on timing, the window may get
    # the keyboard while F11 is still held, and then (correctly, per the
    # protocol) see its release, but it must never see the press.
    if grep -q "kbd key 87 pressed" "$tmp/a.log"; then fail "window saw the panel's key press"; fi
    stop
}

# ---- a pointer device disappears in the middle of a grab ------------------
s9() {
    name="pointer removed during a grab ends the grab"
    start "$root/tests/input/floating.lua" 1
    # Super+drag; the driver exits with the button (and Super) still held,
    # which destroys its virtual pointer: the grab must end with it.
    drive move 600 350 key super down down left move 650 400
    drive move 800 500 sleep 100
    dump                                                                      # 1
    expect 1 "view 2 590,335 200x150 focused=true"
    # Client-side (CSD) move: the client saw the press, so it and the seat
    # must see a release, or the next press never reaches the client.
    drive move 640 380 down left sleep 200 move 660 400
    drive move 900 600 sleep 100
    dump                                                                      # 2
    expect 2 "view 2 610,355 200x150 focused=true"
    drive move 700 420 down left up left sleep 200
    [ "$(grep -c 'csd move requested' "$tmp/a.log")" -eq 2 ] || fail "a press after the removed pointer did not reach the client"
    # Super+right resize from the bottom-right quadrant, pointer removed.
    drive move 780 480 key super down down right move 800 500 sleep 300
    drive move 1000 650 sleep 300
    dump                                                                      # 3
    expect 3 "view 2 610,355 220x170 focused=true"
    stop
}

# ---- a new layer surface must not take the keyboard from an exclusive one -
s10() {
    name="exclusive layer surface keeps the keyboard"
    start "$root/tests/input/floating.lua" 1 panel-kbd   # panel: top, exclusive
    launch od RAYWM_TEST_LAYER=1 RAYWM_TEST_LAYER_LEVEL=overlay RAYWM_TEST_LAYER_KBD=on_demand RAYWM_TEST_KBD=1
    wait_log od "layer frame done"
    press_j
    presses panel 1; presses od 0; presses a 0
    # A higher (overlay) exclusive surface does take it, and gives it back
    # to the panel, not to the window, when it goes away.
    launch ex RAYWM_TEST_LAYER=1 RAYWM_TEST_LAYER_LEVEL=overlay RAYWM_TEST_LAYER_KBD=1 RAYWM_TEST_KBD=1
    wait_log ex "layer frame done"
    press_j
    presses ex 1; presses panel 1
    kill "$(cat "$tmp/ex.pid")"; sleep 0.3
    press_j
    presses panel 2; presses od 0; presses a 0
    # No exclusive surface left: the window gets the keyboard back.
    kill "$(cat "$tmp/panel.pid")"; sleep 0.3
    press_j
    presses a 1; presses od 0
    stop
}

# ---- a toplevel is destroyed while its popup is open ----------------------
s11() {
    name="toplevel destroyed with an open popup"
    start "$root/tests/input/floating.lua" 1
    # B covers A (540,285 200x150); its popup is at 730,425 60x60, partly
    # outside both windows. When the pointer enters the popup, B destroys
    # its toplevel and opens a nested popup on the dying popup (see
    # PopupTest in tests/client.zig).
    launch b RAYWM_TEST_HOLD=1 RAYWM_TEST_POPUP=1 RAYWM_TEST_PTR=1 RAYWM_TEST_ROUNDS=1
    wait_log b "popup mapped"
    drive move 770 470 sleep 300
    wait_log b "popup race sent"
    wait_log b "popup done"
    # Nothing is under the pointer now: a click must reach no client, in
    # particular not the closed window's popup.
    drive down left up left sleep 200
    if grep -q "ptr button" "$tmp/b.log"; then fail "the destroyed window's popup got the click"; fi
    if grep -q "ptr button" "$tmp/a.log"; then fail "A got a click outside its area"; fi
    drive move 600 350 down left up left sleep 200
    grep -q "ptr button 272 pressed window" "$tmp/a.log" || fail "a click on A did not reach it"
    dump                                                                      # 1
    expect 1 "view 2 540,285 200x150 focused=true"
    stop
}

# ---- the seat's active keyboard is unplugged, another one remains ---------
s12() {
    name="unplugging the active keyboard keeps the other one usable"
    start "$root/tests/input/floating.lua" 1
    # K1 stays; K2 (created later, so the seat's active keyboard) goes away.
    env -i PATH="$PATH" XDG_RUNTIME_DIR="$tmp" WAYLAND_DISPLAY="$(cat "$tmp/display")" \
        "$bin/raywm-test-input" sleep 3000 key j down key j up sleep 300 >>"$tmp/k1.log" 2>&1 &
    sleep 0.5
    drive key ctrl down key ctrl up sleep 100
    # A client started now must still get a keymap and keyboard focus.
    launch c RAYWM_TEST_HOLD=1 RAYWM_TEST_KBD=1 RAYWM_TEST_ROUNDS=1
    wait_log c "kbd enter"
    grep -q "kbd keymap" "$tmp/c.log" || fail "new client got no keymap"
    # ... and keys typed on the remaining keyboard reach it.
    wait_log k1 "driver: done"
    grep -q "kbd key 36 pressed" "$tmp/c.log" || fail "key from the remaining keyboard not delivered"
    stop
}

run_scenarios input s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 s12
